.ppa-page{--bg:#07111f;--panel:#101a2a;--panel2:#0d1726;--line:rgba(148,163,184,.18);--text:#f8fafc;--muted:#9aa8bb;--blue:#3b82f6;--green:#22c55e;--orange:#f59e0b;--red:#ef4444;--purple:#8b5cf6}*{box-sizing:border-box}.ppa-page{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif;background:radial-gradient(circle at top,#17233a 0,#07111f 45%,#040912 100%);color:var(--text)}.wrap{max-width:1180px;margin:auto;padding:28px}.hero{display:grid;grid-template-columns:1.2fr .8fr;gap:18px;align-items:stretch}.card{background:linear-gradient(180deg,rgba(16,26,42,.96),rgba(8,15,27,.96));border:1px solid var(--line);border-radius:22px;padding:20px;box-shadow:0 18px 50px rgba(0,0,0,.25)}h1{margin:0 0 8px;font-size:34px;letter-spacing:-.04em}p{margin:0 0 14px}.muted{color:var(--muted)}input[type=file]{display:none}.drop{width:100%;min-height:150px;margin-top:16px;border:2px dashed rgba(59,130,246,.55);border-radius:20px;padding:28px;text-align:center;background:rgba(59,130,246,.06);cursor:pointer;transition:.2s;display:grid;place-items:center;gap:6px}.drop:hover,.drop.drag{border-color:var(--blue);background:rgba(59,130,246,.12)}.dropIcon{font-size:42px;line-height:1}.dropTitle{font-weight:900;color:var(--text);line-height:1.2}.dropSub{color:var(--muted);line-height:1.2}.row{display:flex;gap:10px;flex-wrap:wrap}.pill{border:1px solid var(--line);border-radius:999px;padding:8px 12px;background:#0b1422;color:#dbeafe;font-weight:800;font-size:13px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:16px}.stat{background:var(--panel2);border:1px solid var(--line);border-radius:16px;padding:14px}.stat b{display:block;font-size:24px;margin-top:5px}.decision{font-size:28px;font-weight:950;margin:10px 0}.ok{color:var(--green)}.warn{color:var(--orange)}.bad{color:var(--red)}button{border:0;border-radius:14px;background:var(--blue);color:white;padding:12px 16px;font-weight:900;cursor:pointer}button.secondary{background:#19263a;color:#dbeafe;border:1px solid var(--line)}table{width:100%;border-collapse:collapse;margin-top:12px}th,td{border-bottom:1px solid var(--line);padding:10px;text-align:left;vertical-align:top}th{color:#a9b4c3;font-size:13px}.tag{display:inline-block;border-radius:999px;padding:5px 9px;font-weight:900;font-size:12px}.tag.good{background:rgba(34,197,94,.14);color:#86efac}.tag.neutral{background:rgba(245,158,11,.14);color:#fcd34d}.tag.bad{background:rgba(239,68,68,.14);color:#fca5a5}.hidden{display:none}.bar{height:10px;border-radius:999px;background:#111827;overflow:hidden;border:1px solid var(--line)}.bar>span{display:block;height:100%;background:linear-gradient(90deg,var(--red),var(--orange),var(--green));width:0}.notice{border-left:4px solid var(--blue);padding:12px 14px;background:#0b1422;border-radius:0 12px 12px 0;margin-top:12px}.flags li{margin:6px 0}.mini{font-size:12px;color:#94a3b8}.interview-list{display:grid;grid-template-columns:1fr;gap:10px;margin-top:12px}.interview-card{background:#0b1422;border:1px solid var(--line);border-radius:16px;padding:14px}.interview-card details{margin-top:8px}.interview-card summary{cursor:pointer;color:#bfdbfe;font-weight:800}.answer-expected{margin-top:8px;padding:10px;border-radius:12px;background:rgba(34,197,94,.08);border:1px solid rgba(34,197,94,.2)}td:nth-child(5){background:rgba(34,197,94,.035)}@media(max-width:900px){.hero,.grid{grid-template-columns:1fr}.wrap{padding:16px}h1{font-size:28px}}

