ers": {"good": {"label": "Réduire votre charge pour éviter un dépassement.", "score": 1}, "trap": {"label": "Tenir en vous appuyant sur vos ressources restantes.", "score": 0.5}, "bad": {"label": "Pousser au-delà de vos limites.", "score": 0}}}, {"id": "CIVIL_072", "axis": null, "text": "Lorsque vous êtes confronté à une situation durablement inconfortable, votre réaction la plus fréquente est de :", "answers": {"trap": {"label": "Chercher à vous adapter progressivement.", "score": 0.5}, "good": {"label": "Vous désengager de manière réfléchie.", "score": 1}, "bad": {"label": "Mettre fin à la situation de façon radicale.", "score": 0}}}, {"id": "CIVIL_073", "axis": null, "text": "Face à une situation où votre jugement semble moins clair qu’à l’habitude, vous avez tendance à :", "answers": {"good": {"label": "Différer toute décision engageante.", "score": 1}, "trap": {"label": "Redoubler d’efforts pour rester rationnel.", "score": 0.5}, "bad": {"label": "Vous fier à votre ressenti immédiat.", "score": 0}}}, {"id": "CIVIL_074", "axis": null, "text": "Lorsque vous sentez une accumulation de tensions mineures, vous êtes plutôt enclin à :", "answers": {"good": {"label": "Alléger votre environnement pour éviter une surcharge.", "score": 1}, "trap": {"label": "Gérer chaque tension individuellement.", "score": 0.5}, "bad": {"label": "Ignorer ces tensions jusqu’à saturation.", "score": 0}}}, {"id": "CIVIL_075", "axis": null, "text": "Dans une situation où vos repères habituels ne fonctionnent plus, vous avez tendance à :", "answers": {"trap": {"label": "Reconstruire rapidement de nouveaux repères.", "score": 0.5}, "bad": {"label": "Réaffirmer fortement les anciens.", "score": 0}, "good": {"label": "Tolérer cette phase d’incertitude.", "score": 1}}}, {"id": "CIVIL_076", "axis": null, "text": "Lorsque vous êtes confronté à une contrainte prolongée, votre réaction la plus fréquente est de :", "answers": {"good": {"label": "Adapter progressivement votre engagement.", "score": 1}, "trap": {"label": "Composer avec la contrainte sans modifier votre rythme.", "score": 0.5}, "bad": {"label": "Chercher à rompre la contrainte par l’action.", "score": 0}}}, {"id": "CIVIL_077", "axis": null, "text": "Face à une situation où vous ressentez une perte d’autonomie, vous avez tendance à :", "answers": {"trap": {"label": "Négocier pour retrouver une marge de manœuvre.", "score": 0.5}, "good": {"label": "Accepter temporairement cette perte sans réaction immédiate.", "score": 1}, "bad": {"label": "Réagir pour rétablir votre autonomie.", "score": 0}}}, {"id": "CIVIL_078", "axis": null, "text": "Lorsque vous sentez une saturation émotionnelle, votre stratégie privilégiée est de :", "answers": {"good": {"label": "Créer un espace de récupération avant toute décision.", "score": 1}, "trap": {"label": "Maintenir vos engagements en réduisant l’intensité.", "score": 0.5}, "bad": {"label": "Forcer pour tenir jusqu’au bout.", "score": 0}}}, {"id": "CIVIL_079", "axis": null, "text": "Dans une situation où vous percevez une limite personnelle atteinte, vous avez tendance à :", "answers": {"trap": {"label": "Chercher un ajustement immédiat.", "score": 0.5}, "bad": {"label": "Ignorer cette limite pour continuer.", "score": 0}, "good": {"label": "Respecter cette limite et adapter votre comportement.", "score": 1}}}]};
const CONFIG = {
  minNormal: 15,
  minDys: 20,
  seuilFavorable: 0.75,
  seuilEntretien: 0.60,
  maxBadFavorable: 0.20,
  maxBadEntretien: 0.35,
  minAxisFavorable: 0.50,
  minAxisEntretien: 0.40,
  tooFastRatio: 0.40,
  fastRatio: 0.60,
  overGraceMinutes: 1
};
function norm(s){return (s||'').replace(/&nbsp;/g,' ').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[’']/g,"'").replace(/\s+/g,' ').trim().toLowerCase()}
function parseDate(s){let m=(s||'').match(/(\d{4})-(\d{2})-(\d{2})\s+(\d{2}):(\d{2}):(\d{2})/); if(!m)return null; return new Date(+m[1],+m[2]-1,+m[3],+m[4],+m[5],+m[6]);}
function extractMeta(doc){let text=doc.body.innerText; function get(label){let r=new RegExp(label+'\\s*:\\s*([^\\n]+)','i'); let m=text.match(r); return m?m[1].trim():''}
 return {candidat:get('Candidat'), type:(get('Type')||doc.title||'').toUpperCase().includes('CHASSE')?'CHASSE':(get('Type')||doc.title||'').toUpperCase().includes('CIVIL')?'CIVIL':'SASP', debut:get('Début'), fin:get('Fin'), dys:/Mode\s+DYS\s*:\s*OUI/i.test(text)} }
function extractRows(doc){let rows=[]; [...doc.querySelectorAll('table tbody tr')].forEach(tr=>{let t=[...tr.children].map(td=>td.textContent.trim()); if(t.length>=4 && /^Q\d+/i.test(t[0])) rows.push({num:t[0], question:t[1], answer:t[2], displayed:parseFloat(String(t[3]).replace(',','.')), qid:(tr.getAttribute('data-qid')||'')});}); return rows;}
function findScore(row, bank){let qn=norm(row.question), an=norm(row.answer); const fb=Number.isFinite(row.displayed)?row.displayed:0; let item=(row.qid&&bank.find(q=>q.id===row.qid)) || bank.find(q=>norm(q.text)===qn) || bank.find(q=> qn.includes(norm(q.text).slice(0,70)) || norm(q.text).includes(qn.slice(0,70))); if(!item) return {score:fb, kind:'inconnu', axis:'inconnu', expected:null, found:false}; let entry=Object.entries(item.answers).find(([k,a])=>norm(a.label)===an) || Object.entries(item.answers).find(([k,a])=>an.includes(norm(a.label)) || norm(a.label).includes(an)); if(!entry) return {score:fb, kind:'réponse inconnue', axis:item.axis||'general', expected:item, found:false}; let [kind,a]=entry; return {score:Number(a.score), kind:kind==='trap'||kind==='neutral'?'neutre':kind, axis:item.axis||'general', expected:item, found:true};}
function decide(data){let flags=[], hard=[]; const ratio=data.total?data.score/data.total:0; const badRatio=data.total?data.bad/data.total:0; const axisVals=Object.values(data.axes).map(a=>a.score/a.n); const minAxis=axisVals.length?Math.min(...axisVals):1; if(data.duration!=null){ if(data.duration > data.allowed + CONFIG.overGraceMinutes) flags.push(`Temps dépassé : ${data.duration.toFixed(1)} min pour ${data.allowed} min autorisées.`); if(data.duration < data.allowed*CONFIG.tooFastRatio) flags.push(`Temps très court : ${data.duration.toFixed(1)} min, entretien conseillé pour vérifier la lecture réelle.`); else if(data.duration < data.allowed*CONFIG.fastRatio) flags.push(`Temps court : ${data.duration.toFixed(1)} min, à surveiller.`); } else flags.push('Durée impossible à calculer.'); if(data.mismatches>0) flags.push(`${data.mismatches} réponse(s) non reconnue(s) dans la banque.`); if(minAxis < CONFIG.minAxisEntretien) hard.push(`Axe critique sous ${CONFIG.minAxisEntretien*100}% de moyenne.`); if(badRatio >= CONFIG.maxBadEntretien) hard.push(`Trop de mauvaises réponses : ${(badRatio*100).toFixed(0)}%.`); if(ratio < CONFIG.seuilEntretien) hard.push(`Score global insuffisant : ${(ratio*100).toFixed(0)}%.`);
 if(hard.length) return {level:'bad', label:'AVIS DÉFAVORABLE / ENTRETIEN OBLIGATOIRE', flags:[...hard,...flags]};
 if(ratio>=CONFIG.seuilFavorable && badRatio<=CONFIG.maxBadFavorable && minAxis>=CONFIG.minAxisFavorable && flags.length===0) return {level:'ok', label:'PAS D’ENTRETIEN NÉCESSAIRE', flags:['Profil cohérent avec une validation directe.']};
 return {level:'warn', label:'ENTRETIEN CONSEILLÉ', flags: flags.length?flags:['Score intermédiaire ou axe à surveiller malgré absence de blocage majeur.']}; }
function analyze(html){let doc=new DOMParser().parseFromString(html,'text/html'); let meta=extractMeta(doc); let bank=BANKS[meta.type]||BANKS.SASP; let rows=extractRows(doc); let start=parseDate(meta.debut), end=parseDate(meta.fin); let duration=(start&&end)?(end-start)/60000:null; let allowed=meta.dys?CONFIG.minDys:CONFIG.minNormal; let details=rows.map(r=>({...r,...findScore(r,bank)})); let axes={}, score=0, good=0, neutral=0, bad=0, mismatches=0; details.forEach(d=>{score+=d.score; if(d.score===1)good++; else if(d.score===0.5)neutral++; else bad++; if(!d.found)mismatches++; let ax=d.axis||'general'; axes[ax]=axes[ax]||{score:0,n:0}; axes[ax].score+=d.score; axes[ax].n++;}); let data={meta,rows,details,axes,score,total:details.length,good,neutral,bad,mismatches,duration,allowed}; data.decision=decide(data); return data;}
function pct(x){return (x*100).toFixed(0)+'%'}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));}
function goodAnswer(item){
  if(!item || !item.answers) return null;
  let e=Object.entries(item.answers).find(([k,a])=>Number(a.score)===1) || Object.entries(item.answers).find(([k])=>k==='good');
  return e ? e[1].label : null;
}
function axisLabel(axis){
 const map={controle_emotionnel:'Contrôle émotionnel',desescalade:'Désescalade',proportionnalite:'Proportionnalité / usage de la force',incertitude:'Tolérance à l’incertitude',pression:'Gestion de la pression',autorite_ego:'Rapport à l’autorité / ego',cooperation:'Coopération & ajustement',jugement:'Jugement professionnel',fatigue:'Fatigue & altération cognitive',psychologie:'Psychologie / maîtrise de soi',securite:'Sécurité',general:'Général'};
 return map[axis]||axis||'Général';
}
function explainGap(d){
 if(d.score===0.5) return 'La réponse n’est pas totalement inadaptée, mais elle reste moins prudente ou moins procédurale que la réponse attendue.';
 if(d.score===0) return 'La réponse indique une tendance à agir trop vite, durcir la posture ou réduire l’incertitude par l’action, ce qui doit être clarifié en entretien.';
 if(!d.found) return 'La réponse ou la question n’a pas été reconnue dans la banque. Vérifier que le rapport correspond bien à la banque utilisée.';
 return 'Réponse conforme à la posture attendue.';
}
function makeInterviewQuestion(d){
 const q=String(d.question||'').replace(/^\[[^\]]+\]\s*[–-]\s*/,'').replace(/\s*Vous\s*:\s*$/i,'').trim();
 const expected=goodAnswer(d.expected);
 if(d.score===0.5){
   return `Mise en situation : ${q} Vous avez répondu « ${d.answer} ». Expliquez ce qui vous ferait basculer vers la réponse attendue : « ${expected||'—'} ». Comment l’appliqueriez-vous concrètement ?`;
 }
 return `Mise en situation : ${q} Vous avez choisi « ${d.answer} ». Pourquoi cette réponse peut-elle être risquée ? Donnez une réaction plus adaptée, proche de : « ${expected||'—'} ». `;
}
function renderCorrectionRows(details, mode='all'){
 const filtered=details.filter(d=> mode==='all' ? d.score<1 || !d.found : d.score===0 || !d.found);
 if(!filtered.length) return '<tr><td colspan="6" class="muted">Aucune correction ciblée : toutes les réponses reconnues sont conformes.</td></tr>';
 return filtered.map(d=>{
   const ga=goodAnswer(d.expected) || 'Bonne réponse introuvable dans la banque.';
   return `<tr>
     <td>${esc(d.num)}</td>
     <td>${esc(axisLabel(d.axis))}</td>
     <td>${esc(d.question)}</td>
     <td><span class="tag ${d.score===0.5?'neutral':'bad'}">${esc(d.kind)} · ${d.score} pt</span><br>${esc(d.answer)}</td>
     <td><span class="tag good">bonne réponse · 1 pt</span><br>${esc(ga)}</td>
     <td>${esc(explainGap(d))}</td>
   </tr>`;
 }).join('');
}
function renderInterviewCards(details){
 const targets=details.filter(d=>d.score<1 || !d.found).sort((a,b)=>a.score-b.score).slice(0,12);
 if(!targets.length) return '<div class="notice">Aucune question ciblée à générer : le candidat n’a pas de mauvaise réponse ni de réponse neutre/piège.</div>';
 return targets.map((d,i)=>`<div class="interview-card">
   <div class="mini"><b>${i+1}. ${esc(d.num)}</b> · ${esc(axisLabel(d.axis))} · score ${d.score} pt</div>
   <div style="margin-top:6px">${esc(makeInterviewQuestion(d))}</div>
   <details><summary>Voir la correction attendue</summary><div class="answer-expected">${esc(goodAnswer(d.expected)||'Bonne réponse introuvable.')}</div></details>
 </div>`).join('');
}
function render(data){
 let r=document.getElementById('result'); r.classList.remove('hidden'); let ratio=data.total?data.score/data.total:0; let cls=data.decision.level; let flags=data.decision.flags.map(f=>`<li>${esc(f)}</li>`).join('');
 let axes=Object.entries(data.axes).map(([k,a])=>`<tr><td><b>${esc(axisLabel(k))}</b></td><td>${a.score.toFixed(1)} / ${a.n}</td><td>${pct(a.score/a.n)}</td></tr>`).join('');
 let rows=data.details.map(d=>`<tr><td>${esc(d.num)}</td><td>${esc(d.question)}</td><td>${esc(d.answer)}<br><span class="tag ${d.score===1?'good':d.score===0.5?'neutral':'bad'}">${esc(d.kind)} · ${d.score} pt</span></td><td>${esc(axisLabel(d.axis))}</td></tr>`).join('');
 let badCount=data.details.filter(d=>d.score===0 || !d.found).length;
 let partialCount=data.details.filter(d=>d.score===0.5).length;
 r.innerHTML=`<div class="muted">Résultat d’analyse</div><div class="decision ${cls}">${esc(data.decision.label)}</div><div class="bar"><span style="width:${Math.max(0,Math.min(100,ratio*100))}%"></span></div><div class="grid"><div class="stat">Candidat<b>${esc(data.meta.candidat||'—')}</b></div><div class="stat">Type<b>${esc(data.meta.type)}</b></div><div class="stat">Score<b>${data.score.toFixed(1)} / ${data.total}</b><span class="mini">${(ratio*20).toFixed(1)} / 20</span></div><div class="stat">Durée<b>${data.duration==null?'—':data.duration.toFixed(1)+' min'}</b><span class="mini">Référence : ${data.allowed} min · DYS ${data.meta.dys?'oui':'non'}</span></div><div class="stat">Bonnes<b>${data.good}</b></div><div class="stat">Neutres / pièges<b>${data.neutral}</b></div><div class="stat">Mauvaises<b>${data.bad}</b></div><div class="stat">Entretien ciblé<b>${badCount+partialCount}</b><span class="mini">${badCount} mauvaise(s), ${partialCount} neutre(s)</span></div></div><div class="notice"><b>Points de décision</b><ul class="flags">${flags}</ul></div>
 <h3>Synthèse par axe</h3><table><thead><tr><th>Axe</th><th>Score</th><th>Moyenne</th></tr></thead><tbody>${axes}</tbody></table>
 <h3>Correction ciblée</h3><p class="muted">Affiche la réponse du candidat à côté de la bonne réponse attendue pour faciliter l’explication pendant l’entretien.</p><table><thead><tr><th>N°</th><th>Axe</th><th>Question</th><th>Réponse candidat</th><th>Bonne réponse attendue</th><th>Point à clarifier</th></tr></thead><tbody>${renderCorrectionRows(data.details,'all')}</tbody></table>
 <h3>Questions d’entretien générées selon les erreurs</h3><p class="muted">Ces mises en situation sont construites uniquement depuis les réponses neutres, pièges, mauvaises ou non reconnues.</p><div class="interview-list">${renderInterviewCards(data.details)}</div>
 <h3>Détail recalculé complet</h3><table><thead><tr><th>N°</th><th>Question</th><th>Réponse analysée</th><th>Axe</th></tr></thead><tbody>${rows}</tbody></table>`; r.scrollIntoView({behavior:'smooth'});
}
const drop=document.getElementById('drop'), file=document.getElementById('file'); drop.addEventListener('click',()=>file.click()); drop.addEventListener('keydown',ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();file.click();}}); ['dragenter','dragover'].forEach(e=>drop.addEventListener(e,ev=>{ev.preventDefault();drop.classList.add('drag')})); ['dragleave','drop'].forEach(e=>drop.addEventListener(e,ev=>{ev.preventDefault();drop.classList.remove('drag')})); drop.addEventListener('drop',ev=>handle(ev.dataTransfer.files[0])); file.addEventListener('change',ev=>handle(ev.target.files[0])); function handle(f){if(!f)return; let reader=new FileReader(); reader.onload=()=>{try{render(analyze(reader.result))}catch(e){alert('Analyse impossible : '+e.message)}}; reader.readAsText(f,'utf-8');}
</script>

<?php samr_layout_end(); ?>
